import logging
import re
from taf.collectors.netcat.collector import FilteringNetcatCollector, SimpleNetcatCollector
from taf.collectors.core.factories.named_factory import NamedComponentFactory
from taf.collectors.core.templates.dynamic_class_creation import Creating

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class NetcatCollectorFactory(NamedComponentFactory):
    """
           factory to create netcat collectors
    """
    _product_class = FilteringNetcatCollector
    _optional_parameters = {"nc_path", "options", "ip_address", "port", "target_file_name", "iterator", "start_timeout",
                            "stop_timeout", "filter_func"}


class RemoteNetcatCollectorFactory(Creating("tool_executor", "SshExecutor", "executor"),
                                   Creating("file_getter", "LocalFileGetter"),
                                   NetcatCollectorFactory):
    pass


class LocalNetcatCollectorFactory(Creating("tool_executor", "LocalExecutor"),
                                  Creating("file_getter", "LocalFileGetter"),
                                  NetcatCollectorFactory):
    pass


class LocalNetcatCollectorBasicFactory(Creating("tool_executor", "LocalExecutor"),
                                       Creating("file_getter", "LocalFileGetter"),
                                       NamedComponentFactory):
    _product_class = SimpleNetcatCollector
    _optional_parameters = {"nc_path", "options", "ip_address", "port", "target_file_name", "start_timeout",
                            "stop_timeout"}


class NetcatCollectorFactorySelector(object):

    def create(self, configuration, existing_arguments):
        if "capture_filter" in configuration:
            configuration["filter_func"] = self._get_filter_func(configuration["capture_filter"])
        if "executor" in configuration:
            factory_class = RemoteNetcatCollectorFactory
        elif "filter" in configuration or "iterator" in configuration:
            factory_class = LocalNetcatCollectorFactory
        else:
            factory_class = LocalNetcatCollectorBasicFactory
        return factory_class().create(
            configuration=configuration,
            existing_arguments=existing_arguments)

    @staticmethod
    def _get_filter_func(capture_filter):
        if callable(capture_filter):
            filter_func = capture_filter
            logger.debug("Filter Function is callable")
        else:
            def filter_func(line):
                return bool(re.match(capture_filter.encode('utf-8'), line))

            logger.debug("Filter Function is created using Regex string")
        return filter_func
